export function moveGrade(a,played){if(!a||a.engine!=='stockfish')return {label:'Analyzing…',kind:'pending'};if(a.bestCode===played)return {label:'Best move',kind:'best'};const loss=a.loss;return loss<=35?{label:'Good move',kind:'good'}:loss<=90?{label:'Decent move',kind:'decent'}:loss<250?{label:'Mistake',kind:'mistake'}:{label:'Blunder',kind:'blunder'}}
export function evaluation(a,color){if(!a||a.engine!=='stockfish')return {text:'—',white:50,description:'Evaluation pending'};const sign=color==='w'?1:-1,cp=a.actualScore*sign,mate=a.actualMate==null?null:a.actualMate*sign;return {text:mate!=null?(mate>0?'+':'−')+'M'+Math.abs(mate):(cp>=0?'+':'')+(cp/100).toFixed(1),white:Math.max(3,Math.min(97,50+45*Math.tanh(cp/500))),description:mate!=null?(mate>0?'White':'Black')+' has a forced mate':Math.abs(cp)<30?'Roughly equal':(cp>0?'White':'Black')+' is ahead'}}
